86	182:     public static FValue radixPoint(FloatLiteralExpr x) {
87	183:         synchronized (Numerals.class) {
88	184:             Site s = sites.get(x);
89	185:             if (s != null) return s.value;
90	186:             // The radix as written: the node's base is 1 where every digit after the point is 0.
91	187:             int r = radixOf(x.getText());
92	188:             int m = x.getDenomPower();
93	189:             BigInteger v = x.getIntPart().multiply(BigInteger.valueOf(r).pow(m)).add(x.getNumerator());
94	190:             int n = Math.max(1, digitPart(x.getText()).length());
95	191:             // The digits as written: the node keeps the value, not the trailing zeros.
96	192:             String t = x.getText().replace("'", "").replace("\u202F", "");
97	193:             int under = t.indexOf('_');
98	194:             String written = under >= 0 ? t.substring(0, under) : t;
99	195:             int point = written.indexOf('.');
100	196:             if (point >= 0) {
101	197:                 String digits = written.substring(0, point) + written.substring(point + 1);
102	198:                 if (r == 12) digits = digits.replace('x', 'A').replace('X', 'A').replace('e', 'B').replace('E', 'B');
103	199:                 try {
104	200:                     BigInteger w = new BigInteger(digits, r);
105	201:                     int wm = written.length() - point - 1;
106	202:                     if (w.multiply(BigInteger.valueOf(r).pow(m)).equals(v.multiply(BigInteger.valueOf(r).pow(wm)))) {
107	203:                         v = w;
108	204:                         m = wm;
109	205:                         n = digits.length();
110	206:                     }
111	207:                 }
112	208:                 catch (NumberFormatException ex) {
113	209:                     // the node's numbers stand
114	210:                 }
115	211:             }
116	212:             s = new Site(n, m, r, v, true);
117	213:             double d = simpleDoubleArith.numeralToDouble(v, r, m);
118	214:             s.value = new FloatNumeral(d, s);
119	215:             s.plain = FFloat.make(d);
120	216:             sites.put(x, s);
